#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *h = malloc((size_t)n * sizeof(int));
    int *right_max = malloc((size_t)n * sizeof(int));

    for (int i = 0; i < n; i++) {
        scanf("%d", &h[i]);
    }

    int maximum = 0;
    for (int i = n - 1; i >= 0; i--) {
        if (h[i] > maximum) maximum = h[i];
        right_max[i] = maximum;
    }

    int count = 0;
    maximum = 0;
    for (int i = 0; i < n; i++) {
        if (h[i] > maximum) maximum = h[i];
        int water_level = maximum < right_max[i] ? maximum : right_max[i];
        if (water_level > h[i]) count++;
